t);display:flex;align-items:center;gap:8px;text-align:left;padding:7px 8px;font:inherit;cursor:pointer}.repair-bar>button:disabled{opacity:.55;cursor:wait}.repair-bar span,.repair-bar strong,.repair-bar small{display:block}.repair-bar strong{font-size:9px;color:var(--text)}.repair-bar small{font-size:8px;line-height:1.35;color:var(--faint);margin-top:2px}.warnings-head{min-height:38px;display:flex;align-items:center;justify-content:space-between;gap:6px;padding:5px 8px;border-bottom:1px solid var(--border)}.warnings-head strong{font-size:9px}.warnings-head>span{display:flex;gap:4px}.warnings-head button,.empty button{height:23px;border:1px solid var(--border);background:var(--surface);color:var(--muted);font:inherit;font-size:8px;border-radius:4px;padding:0 6px;cursor:pointer;display:flex;align-items:center;gap:3px}.checks{min-height:0;flex:1;overflow:auto;padding:7px}.checks article{display:grid;grid-template-columns:21px minmax(0,1fr) 12px;gap:6px;padding:8px 5px;border:1px solid var(--border);border-radius:5px;background:var(--bg);margin-bottom:5px;color:#d0a04f}.checks article.error{color:#cf6e68}.checks article.info{color:#5ead7b}.checks .icon{width:19px;height:19px;border-radius:4px;background:currentColor;display:grid;place-items:center}.checks .icon :global(svg){color:var(--bg)}.checks article>div>strong{display:block;font-size:9px;line-height:1.35;color:var(--text);font-weight:550}.checks small{font-size:8px;color:var(--faint);display:block;margin-top:4px}.checks footer{display:flex;gap:4px;margin-top:7px}.checks footer button{height:20px;border:1px solid var(--border);background:var(--surface);color:var(--faint);border-radius:3px;font:inherit;font-size:8px;display:flex;align-items:center;gap:3px;padding:0 5px;cursor:pointer}.checks footer button.repair{color:var(--accent)}.caveat{font-size:8px;line-height:1.4;color:var(--faint);padding:0 10px 10px;margin:0}.empty{height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;color:var(--faint);padding:20px}.empty strong{font-size:11px;color:var(--text);margin-top:10px}.empty p{font-size:9px;line-height:1.45}.empty button{margin-top:8px;height:27px;background:var(--text);color:var(--bg);border-color:var(--text)}
</style>
